/*
 * Settings for local development of the landing pages.
 *
 * The live sites are generated by build.py, which writes a config.js for
 * each site (language, brand, webhook, legal links). Edit the SITES list in
 * build.py to change those, not this file.
 */
window.LP_CONFIG = {
  brand: '305-EN-DOLOR',
  owner: 'LegalNow247.com LLC',
  siteUrl: 'https://305endolor.com',

  // '' lets visitors switch language; 'es' or 'en' locks the site to one.
  lang: '',

  // Legal links; {lang} becomes "en" or "es". Leave a link empty to hide it.
  links: {
    privacy: 'https://305endolor.com/{lang}/privacy',
    terms: 'https://305endolor.com/{lang}/terms',
    disclosures: 'https://305endolor.com/{lang}/state-disclosures'
  },

  // Where completed quiz leads are POSTed. Empty while developing, so test
  // leads are only printed to the browser console.
  webhookUrl: '',

  // 'json' (default, best for GoHighLevel) or 'form' (form encoded, for
  // webhooks that reject requests sent from a browser).
  webhookFormat: 'json',

  // Optional: send people to a thank you page after submitting instead of
  // showing the in page confirmation. "{lang}" is replaced with "en" or "es".
  redirectUrl: ''
};
